(x, y, t) => {
  const s = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90],
    [120+Math.sin(t*0.8+4)*80, 180+Math.cos(t*0.6+3)*60],
    [360+Math.cos(t*0.4+1)*90, 60+Math.sin(t*0.9+2)*40]
  ];
  const waves = s.map((p,i) => {
    const d = Math.sqrt((x-p[0])**2+(y-p[1])**2);
    return Math.sin(d*[0.08,0.1,0.06,0.09,0.07][i] - t*[2,1.7,2.3,1.9,2.1][i]);
  });
  const activator = waves.reduce((a,w)=>a+w,0)/5;
  const inhibitor = (Math.sin(x*0.05+y*0.03+t*0.8)+Math.sin(x*0.03-y*0.05+t*1.1)+Math.sin(x*0.04+y*0.06-t*0.6))/3;
  const fine = Math.sin((x+y)*0.15+t*3)*0.15+Math.sin((x-y)*0.12-t*2.5)*0.15+Math.sin(x*0.2-y*0.1+t*1.5)*0.1;
  const warpX = Math.sin(y*0.02+t*0.5)*15+Math.cos(x*0.015-t*0.3)*10;
  const warpY = Math.sin(x*0.02-t*0.4)*15+Math.cos(y*0.015+t*0.35)*10;
  const wx=x+warpX, wy=y+warpY, cx=240, cy=120;
  const dist=Math.sqrt((wx-cx)**2+(wy-cy)**2), ang=Math.atan2(wy-cy,wx-cx);
  const radial=Math.sin(dist*0.04-t*1.5), angular=Math.sin(ang*6+t*0.4), spiral=Math.sin(ang*3+dist*0.02-t*0.8);
  const pattern2=Math.tanh((radial+angular*0.5+spiral*0.3)*2);
  const reaction=activator-inhibitor*0.8+fine;
  const spot=Math.tanh(reaction*2.5);
  const feed=spot*pattern2;
  const blend=Math.tanh((spot*0.5+pattern2*0.35+feed*0.15)*2.5);
  const v=blend*0.5+0.5;
  const pal=[[8,12,52],[12,45,95],[18,95,125],[30,155,145],[75,195,160],[200,215,120],[245,185,70],[225,110,55],[155,45,55],[70,18,58],[8,12,52]];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.82+Math.sin(reaction*Math.PI)*0.12+Math.sin(dist*0.03-t)*0.06;
  return [
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum)|0
  ];
}
